import{_ as e,o as l,c as t,ag as a}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Redis 面试题","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/redis/redis.md","filePath":"interviews/redis/redis.md","lastUpdated":1754288988000}'),d={name:"interviews/redis/redis.md"};function r(s,i,o,n,h,c){return l(),t("div",null,[...i[0]||(i[0]=[a('<h1 id="redis-面试题" tabindex="-1">Redis 面试题 <a class="header-anchor" href="#redis-面试题" aria-label="Permalink to &quot;Redis 面试题&quot;">​</a></h1><h2 id="什么是nosql" tabindex="-1">什么是NoSQL? <a class="header-anchor" href="#什么是nosql" aria-label="Permalink to &quot;什么是NoSQL?&quot;">​</a></h2><p>NoSQL（Not Only SQL）指非关系型数据库。常见NoSQL如下:</p><ul><li>键值型：Redis、DynamoDB</li><li>文档数据库：MongoDB、CouchDB</li><li>宽列数据库: Cassandra、HBase</li><li>图数据库: Neo4J、Graph</li></ul><h2 id="sql和no-sql有什么区别" tabindex="-1">SQL和No SQL有什么区别？ <a class="header-anchor" href="#sql和no-sql有什么区别" aria-label="Permalink to &quot;SQL和No SQL有什么区别？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项目</th><th>SQL 数据库</th><th>NoSQL 数据库</th></tr></thead><tbody><tr><td>数据模型</td><td>结构化</td><td>非结构化</td></tr><tr><td>事务</td><td>支持</td><td>不完全支持</td></tr><tr><td>性能</td><td>取决于硬盘速度、索引结构</td><td></td></tr><tr><td>扩展</td><td>读写分离、分库分表</td><td>横向扩展（加机器）</td></tr></tbody></table><h2 id="什么是redis" tabindex="-1">什么是Redis？ <a class="header-anchor" href="#什么是redis" aria-label="Permalink to &quot;什么是Redis？&quot;">​</a></h2><p>Redis：REmote DIctionary Server</p><ul><li>Redis是一个使用 C 语言开发的开源 NoSQL 键值型数据库。</li><li>Redis 的数据保存在内存中的，读写速度非常快，并且支持持久化</li><li>Redis被广泛应用于分布式缓存、分布式锁等</li></ul><h2 id="redis提供了哪些数据类型" tabindex="-1">Redis提供了哪些数据类型？ <a class="header-anchor" href="#redis提供了哪些数据类型" aria-label="Permalink to &quot;Redis提供了哪些数据类型？&quot;">​</a></h2><p>基础数据类型</p><ul><li>LIST</li><li>STRING</li><li>HASH</li><li>SET</li><li>ZSET（Sorted SET）</li></ul><p>高级数据类型</p><ul><li>Bitmap</li><li>BitFiled</li><li>Bloom filter</li><li>HyperLogLog</li><li>Geo</li><li>Stream</li></ul><h2 id="redis为什么这么快" tabindex="-1">Redis为什么这么快？ <a class="header-anchor" href="#redis为什么这么快" aria-label="Permalink to &quot;Redis为什么这么快？&quot;">​</a></h2><ol><li><strong>纯内存操作</strong>, 这是主要原因, 内存IO速度远高于磁盘IO</li><li><strong>高效的 I/O 模型</strong>. 使用单线程事件循环配合 I/O 多路复用技术，让单个线程可以同时处理多个网络连接上的 I/O 事件（如读写），避免了多线程模型中的上下文切换和锁竞争问题。</li><li><strong>高效的底层数据结构</strong>. Redis提供的数据类型, 其内部实现采用高度优化的编码方式（如 ziplist, quicklist, skiplist, hashtable 等）。Redis 会根据数据大小和类型动态选择最合适的内部编码，以在性能和空间效率之间取得最佳平衡。</li><li><strong>高效的通信协议</strong>. Redis 设计的 RESP (REdis Serialization Protocol) 协议, 简单高效、解析性能好，并且是二进制安全的。客户端和服务端之间通信的序列化/反序列化开销很小，有助于提升整体的交互速度。</li></ol><h2 id="redis那么快为什么不用来当主数据库" tabindex="-1">Redis那么快为什么不用来当主数据库? <a class="header-anchor" href="#redis那么快为什么不用来当主数据库" aria-label="Permalink to &quot;Redis那么快为什么不用来当主数据库?&quot;">​</a></h2><ol><li>内存成本高</li><li>Redis的持久化仍然有数据丢失风险</li></ol><h2 id="除了-redis-还有哪些分布式缓存方案" tabindex="-1">除了 Redis，还有哪些分布式缓存方案？ <a class="header-anchor" href="#除了-redis-还有哪些分布式缓存方案" aria-label="Permalink to &quot;除了 Redis，还有哪些分布式缓存方案？&quot;">​</a></h2><ul><li>Memcached</li><li>Dragonfly：一种针对现代应用程序负荷需求而构建的内存数据库，完全兼容 Redis 和 Memcached 的 API</li><li>KeyDB： Redis 的一个高性能分支，专注于多线程、内存效率和高吞吐量</li><li>ValKey：Redis闭源后, 由原 Redis 核心开发者社区发起的一个完全开源、社区主导 的 Redis 分支</li><li>Tendis: 腾讯开源的, 基于RocksDB, 兼容Redis 4.0, 社区不活跃, 不建议使用</li></ul>',20)])])}const S=e(d,[["render",r]]);export{u as __pageData,S as default};
